script:
frappe.ui.form.on('ToDo', {
    onload: function(frm) {
        frappe.msgprint("Client Script fired on form load!");
    },
    after_save: function(frm) {
        frappe.utils.play_sound("ping");
    }
});

frappe.ui.form.on("Braintree Payment Test", {
    refresh(frm) {
        frm.add_custom_button("Simulate Payment Success", function() {
            frappe.call({
                method: "library_management.integrations.test_braintree_success",
                args: {
                    reference_doctype: frm.doc.reference_doctype,
                    reference_docname: frm.doc.reference_docname
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.msgprint("Redirecting to: " + r.message);
                        window.location.href = r.message;
                    }
                }
            });
        });
    }
});

frappe.ui.form.on('Book', {
    refresh(frm) {
        frappe.show_alert({
            message: 'Book Form Opened',
            indicator: 'green'
        });
    }
});

frappe.ui.form.on('User', {
	refresh(frm) {
		frm.add_custom_button("Send Welcome Email",function(){
		    frappe.msgprint("Email Sent")
		},"Actions")
	}
})
